const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const repoStatusResponse = await fetch(`${runnerBase}/repo/status`, { headers });
if (!repoStatusResponse.ok) throw new Error(`repo/status failed: ${repoStatusResponse.status}`);
const repoStatus = await repoStatusResponse.json();

const mapResponse = await fetch(`${runnerBase}/jobs`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ action: 'codebase_map_refresh', mode: 'sync', args: [] }),
});
const rawMap = await mapResponse.text();
if (!mapResponse.ok) throw new Error(`codebase_map_refresh failed: ${mapResponse.status} ${rawMap}`);
const mapResult = rawMap ? JSON.parse(rawMap) : {};
const mapJson = mapResult.stdout ? JSON.parse(mapResult.stdout) : {};

const repoStatusPutResponse = await fetch(`${runnerBase}/context/repo-status`, {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: repoStatus }),
});
if (!repoStatusPutResponse.ok) {
  const body = await repoStatusPutResponse.text();
  throw new Error(`context/repo-status failed: ${repoStatusPutResponse.status} ${body}`);
}
const contextRefreshResponse = await fetch(`${runnerBase}/context/context-refresh`, {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: { refreshedAt: new Date().toISOString(), repoStatus, mapJson } }),
});
if (!contextRefreshResponse.ok) {
  const body = await contextRefreshResponse.text();
  throw new Error(`context/context-refresh failed: ${contextRefreshResponse.status} ${body}`);
}

const reportRelativePath = `context-refresh/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Context Manager Refresh',
  '',
  `Generated: ${new Date().toISOString()}`,
  '',
  '## Repo Status',
  '',
  '```json',
  JSON.stringify(repoStatus, null, 2),
  '```',
  '',
  '## Codebase Map',
  '',
  '```json',
  JSON.stringify(mapJson, null, 2),
  '```',
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);

return [{ json: { generatedAt: new Date().toISOString(), repoStatus, mapJson, reportRelativePath } }];
